import crypto from 'node:crypto'
import { assertSize, assertRandomTarget } from './utils/assertSize.mjs'
import { fromUint8Super } from './utils/output.mjs'

if (!crypto.webcrypto) throw new Error('Unexpected crypto-browserify or old Node.js crypto')

/** @deprecated Use `import { randomValues } from '@exodus/crypto/randomBytes'` */
export function randomBytes(size) {
  assertSize(size)
  return crypto.randomBytes(size)
}

// Not async by default to avoid potential errors with not awaiting
export function randomFill(target) {
  assertRandomTarget(target)
  crypto.randomFillSync(target)
  return target
}

export function randomValues(size, format = 'uint8') {
  return fromUint8Super(randomBytes(size), format)
}
